from pathlib import Path
import json,uuid,hashlib
root=Path(__file__).resolve().parents[2];sample=root/'samples/OrderPractice';records=[]
def identity(name):return '{'+str(uuid.uuid5(uuid.NAMESPACE_URL,'dph:order-practice:'+name)).upper()+'}'
def card(category,name,meaning,example,limits,help_text,practice,target='',kind='component',role='All learners'):
 record={'record_type':'learning_card','card_id':identity(name),'category':category,'fields':dict(name=name,role=role,meaning=meaning,example=example,limits=limits,help=help_text,practice=practice)}
 records.append({'record':record,'source_name':target,'source_kind':kind})
records.append({'record':{'record_type':'project_profile','fields':{'purpose':'Practice order is a small learning example. Enter a whole-item quantity and a unit price, optionally add the example tax, and calculate the displayed total. It does not save orders, transfer money, use a database or contact a service.','owner':'DPH practice lesson author','support':'Use the supplied worked examples and source explanations. This is sample teaching material, not a supported sales system.','architecture':'One form contains two input boxes, one option, a Calculate total button and a result label. CalculateClick validates input, calculates a subtotal, optionally adds tax and displays the total.','evidence':'Authored specifically for the supplied OrderForm.pas and OrderForm.fmx. Source hashes are checked before importing these lessons. These are example contributions; saving them does not confer independent human verification.'}},'source_name':''})
card('Screen','What the practice screen does','This screen teaches one input-to-result route. Work from the quantity and price to the optional tax, then Calculate total and the result.','Quantity 2 and price 10.00 give 20.00 without tax.','This is a learning example, not an ordering or payment system.','If the result is not calculated, read the input guidance and the exact error message.','Name the input, action and result. Expected: quantity and price; Calculate total; displayed total.','CalculateButton')
card('Field','Quantity: how many whole items','Quantity counts whole items. A whole number means it has no fractional part.','Enter 2 for two items. Entering 2.5 is invalid because this example handles whole items.','Allowed values are whole numbers from 1 to 1000. Zero, negative values and larger quantities are rejected.','If you see Enter a whole quantity from 1 to 1000., replace the value with a whole number in that range and calculate again.','Is 0 valid? Expected: no; the minimum is 1. Is 3 valid? Expected: yes.','QuantityEdit')
card('Field','Unit price: price for one item','Unit price is the amount for one item, in arbitrary practice units. A decimal point separates whole and fractional units.','10.00 means ten practice units per item. At quantity 2, the subtotal is 20.00.','Allowed values are from 0 to 10000. Use a decimal point rather than a comma; this is an explicit rule of this sample.','If you see Enter a price from 0 to 10000, using a decimal point., correct the value and calculate again.','At price 5.00 and quantity 3, what is the subtotal? Expected: 15.00.','PriceEdit')
card('Setting or option','What the tax option changes','The checkbox chooses whether the example adds ten percent of the subtotal. Checked adds tax; unchecked adds none.','Quantity 2 and price 10.00: unchecked gives 20.00; checked gives 22.00.','Ten percent is a teaching rule, not a statement of any real tax law.','If your result differs by ten percent, check this option before assuming the calculation failed.','With subtotal 30.00, how much example tax is added? Expected: 3.00, for a total of 33.00.','TaxCheck')
card('Business rule','How the total is calculated','Multiply quantity by unit price to get the subtotal. If tax is selected, calculate ten percent of that subtotal. Add the tax to get the total.','3 items at 5.00: subtotal 15.00; optional tax 1.50; total 16.50 with tax or 15.00 without it.','The sample displays two decimal places. It is not a production financial calculation or a currency conversion.','Compare quantity, unit price and checkbox state with the worked example.','Explain the order. Expected: validate inputs, multiply, choose tax, add, display.','CalculateClick','routine')
card('Output or report','Reading the displayed total','The result label displays the result of the last successful calculation. Total: not calculated means no valid result is currently displayed.','Quantity 2, price 10.00 and tax checked display Total: 22.00.','Click Calculate total after changing an input. Changing an input alone does not recalculate the label. No report file is produced.','If the label says not calculated, correct the input error and calculate again.','Does changing quantity immediately update the result? Expected: no; calculate again.','ResultLabel')
card('Error or problem','Enter a whole quantity from 1 to 1000.','The quantity is missing, not a whole number, or outside the supported range. Calculation stops before showing a new total.','Blank, 0, -1, 2.5 and 1001 are invalid; 2 is a safe example.','Do not treat an old remembered result as the current calculation. The label is reset before validation.','Replace the quantity with a whole number from 1 to 1000, dismiss the message and click Calculate total again.','What should you do with 2.5? Expected: use a whole quantity, such as 2, if that matches the task.','CalculateClick','routine')
card('Error or problem','Enter a price from 0 to 10000, using a decimal point.','The price could not be read as a number or falls outside the permitted range.','10.00 is a valid example. A negative price is not.','This sample explicitly uses a decimal point. It does not guess another number format.','Dismiss the message, enter a price in range with a decimal point, and calculate again.','Is -5.00 valid? Expected: no; the minimum price is zero.','CalculateClick','routine')
card('Question and answer','Why did changing a field not change the total?','The button starts the calculation. Editing a value does not automatically run CalculateClick.','Calculate 2 at 10.00, then change quantity to 3. Click Calculate total to display 30.00 without tax.','A displayed result can belong to earlier input until you calculate again.','Check the inputs and tax option, then click Calculate total.','What event starts the calculation? Expected: the Calculate total button click.','CalculateButton')
card('Question and answer','Where is my order saved?','Nowhere. This example only displays a calculation. It contains no order storage or payment action.','Closing the sample does not save an order record.','Do not use this example to place a real order or enter real customer information.','Use fictional values while learning. Ask the owner about storage in your actual selected application.','Does a successful calculation prove an order was saved? Expected: no.','CalculateClick','routine')
card('Role or permission','Who this example is for','The sample is for a new learner practicing how inputs, a button, a choice and a result fit together. No sign-in or role permission system is implemented.','Begin with the First day path and use only fictional values.','These are teaching roles for filtering lessons, not access-control permissions.','Return to Start here or ask the person preparing lessons if you need a different learning route.','Does a learning role grant permission to use a production application? Expected: no.')
card('Related system','What this example depends on','The sample uses Delphi FMX to display its form. It has no database, external service, printer or network dependency in its calculation.','The total is prepared by CalculateClick and placed in ResultLabel.','This explanation applies only to this supplied example. Your own application may have different dependencies.','For another program, ask which systems are needed and what users should do when they are unavailable.','Must this sample contact a payment service to calculate? Expected: no.')
card('History or design choice','Why this example is deliberately small','One screen makes the whole input-to-result route easy to follow before studying a larger application. The visible calculation has one option and two validation checks.','Follow CalculateButton to CalculateClick, then read its choices and output.','This example does not promise that a real application has only one screen or one operation.','When studying a larger application, begin with one familiar action and its expected result.','What is a good first scope for learning a large program? Expected: one common task and its result.')
card('Learning check','Check your understanding of the example','You are ready to move on when you can name the inputs, describe the tax choice, explain one invalid input and predict a result.','2 at 10.00 without tax gives 20.00; with tax gives 22.00.','Being able to repeat a result is different from understanding why it occurs. Explain it in your own words.','Return to the field, rule or error explanation that answers the part you cannot yet explain.','Predict 4 at 2.50 with tax. Expected: subtotal 10.00, tax 1.00, total 11.00.')
tasks=[
 ('Meet the practice application','Identify the screen, inputs, action and result before learning its code.','Open the supplied practice lessons; no customer application is needed.','Explain the screen in your own words.','Use Learning library to read the screen and field meanings.','Name the inputs and result. Expected: quantity, price and optional tax; displayed total.',[
 ('Read Start here in Learn the project.','Recognize that the sample calculates a practice total without saving orders or transferring money.'),
 ('Choose Learning library and read What the practice screen does.','Identify Quantity, Unit price, the tax option, Calculate total and the result label.'),
 ('Read Quantity: how many whole items and Unit price: price for one item.','Explain the valid ranges and give one valid example for each input.')]),
 ('Predict a total without tax','Learn how two inputs become one displayed result.','Read the quantity and unit-price explanations. This lesson can be completed by reading; DPH does not launch the sample.','Predict the documented total of 20.00.','If your prediction differs, multiply quantity by price and confirm tax is not selected.','Predict 3 at 5.00 without tax. Expected: 15.00.',[
 ('Read the worked example in How the total is calculated. Use quantity 2 and unit price 10.00.','Identify a subtotal of 20.00.'),
 ('Leave the example tax out of your prediction.','Tax contributes zero.'),
 ('Read Reading the displayed total and compare its example.','State that the button would display Total: 20.00 for these inputs without tax.')]),
 ('Compare the tax alternatives','Understand how one option changes the result.','Complete Predict a total without tax.','Explain why 20.00 becomes 22.00 with the example tax.','Read What the tax option changes; ten percent of 20.00 is 2.00.','Predict 3 at 5.00 with tax. Expected: 16.50.',[
 ('Read What the tax option changes.','Identify checked and unchecked alternatives.'),
 ('Follow CalculateButton to CalculateClick in Follow an action or Explain.','Locate the choice that tests TaxCheck.IsChecked.'),
 ('Compare the two worked totals.','Explain that the checked option adds 2.00 to a subtotal of 20.00.')]),
 ('Understand an input error safely','Learn what an input message means and how to recover.','Read the Quantity explanation. Do not enter real customer information.','Describe the safe correction for an invalid quantity.','Use the exact error topic in Learning library.','Would quantity 1001 be accepted? Expected: no; the maximum is 1000.',[
 ('Find Enter a whole quantity from 1 to 1000. in Learning library.','Identify what causes this message.'),
 ('Read its worked examples and safe next step.','Explain why 2.5 fails and how a suitable whole quantity avoids that error.'),
 ('Read Reading the displayed total.','Explain why not calculated is not a valid new total.')])]
for order,(name,purpose,pre,result,trouble,practice,steps) in enumerate(tasks,1):
 record={'record_type':'learning_lesson','lesson_id':identity(name),'fields':dict(name=name,purpose=purpose,prerequisites=pre,expected_result=result,troubleshooting=trouble,practice=practice),'steps':[dict(action=a,expected_result=e) for a,e in steps],'learning':{'role':'New learner','path':'First day','order':order}}
 records.append({'record':record,'source_name':''})
images=[]
for filename,kind,caption in [('practice-screen.png','Screenshot','Actual native practice application captured by the DPH sample test: quantity 2, price 10.00, tax off, total 20.00.'),('practice-result.png','Sample output','Actual native practice application result captured by the DPH sample test: quantity 2, price 10.00, tax on, total 22.00.')]:
 p=sample/filename
 if p.exists():images.append({'file':filename,'kind':kind,'caption':caption})
for row in records:
 record=row['record']
 if record.get('record_type')!='learning_card':continue
 if record['fields']['name']=='Reading the displayed total' and (sample/'practice-result.png').exists():record['picture']={'image_sha256':hashlib.sha256((sample/'practice-result.png').read_bytes()).hexdigest(),'x':5000,'y':7500}
 if record['fields']['name']=='Quantity: how many whole items' and (sample/'practice-screen.png').exists():record['picture']={'image_sha256':hashlib.sha256((sample/'practice-screen.png').read_bytes()).hexdigest(),'x':4375,'y':3925}
pack={'version':1,'source_hashes':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(sample.iterdir()) if p.suffix in {'.pas','.fmx','.dpr','.dproj','.png'}},'records':records,'images':images}
(sample/'lessons.json').write_text(json.dumps(pack,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
(sample/'README.txt').write_text('DPH supplied practice application\n\nIn DPH, click Try practice example. Start with Learn a task and the First day path.\nThe prepared lessons explain this sample without running it. Study its fields, worked totals, choice, errors and practice answers in Learning library.\nThis sample does not save orders, transfer money or contact a service. Use fictional values only.\nSource and form files are included for inspection. DPH checks their hashes before loading the supplied lesson pack; edited source requires a review of those lessons.\nThe sample is separate from customer applications and from DPH itself.\n',encoding='utf-8')
print('Prepared',len(records),'attributed sample records with source hashes')
